        public static List<RouteDetails> GetAllStops(int aiSchoolId, int aiAcademicYearId)
        {
            string sSelectStatement = "Select StopId" +
                                      ",0 as RouteStopId" +
                                      ",0 as RouteShiftTimingDetailsId " +
                                      ",StopName" +
                                      " From " +
                                      " Transport.StopMaster " +
                                      " Where " +
                                      " SchoolId= " + aiSchoolId +
                                      " AND Academic_Year_Id= " + aiAcademicYearId +
                                      " AND Is_Deleted=0 "+
                                      " ORDER BY StopName ";

            using (SQLServerDbUtility oSQLServerDbUtility = new SQLServerDbUtility())
            {
                List<RouteDetails> olstclsRouteDetails = new List<RouteDetails>();
                using (SqlDataReader oSqlDataReader = oSQLServerDbUtility.ExecuteSqlStatementAndGetResults(sSelectStatement))
                {
                    RouteDetails oRouteDetails;
                    while (oSqlDataReader.Read())
                    {
                        oRouteDetails = new RouteDetails
                        {
                            miStopId = Convert.ToInt32(oSqlDataReader["StopId"]),
                            msStopName = Convert.ToString(oSqlDataReader["StopName"]),
                            miRouteStopId = Convert.ToInt32(oSqlDataReader["RouteStopId"]),
                            miRouteShiftTimingDetailsId = Convert.ToInt32(oSqlDataReader["RouteShiftTimingDetailsId"])

                        };
                        olstclsRouteDetails.Add(oRouteDetails);
                    }
                    return olstclsRouteDetails;
                }
            }
        }

        /// <summary>
        /// This method is used to get all Routes.
        /// </summary>
        /// <param name="aiUserId"></param>
        /// <returns></returns>
        public List<TransportRoutes> GetAllRoutes()
        {
            List<TransportRoutes> lstTransportRoute = new List<TransportRoutes>();
            using (SQLServerDbUtility oSQLServerDbUtility = new SQLServerDbUtility())
            {
                oSQLServerDbUtility.AddParameter("SchoolId", this.miSchoolId, SqlDbType.Int);
                oSQLServerDbUtility.AddParameter("AcademicYearId", this.miAcademicYearId, SqlDbType.Int);
                using (SqlDataReader oSqlDataReader = oSQLServerDbUtility.ExecuteStoredProcedureAndGetresult("Transport.usp_GetAllRoutes"))
                {
                    while (oSqlDataReader.Read())
                    {
                        TransportRoutes oRouteDetails = new TransportRoutes
                        {
                            RouteId = oSqlDataReader["RouteId"].ToInt(),
                            RouteName = oSqlDataReader["RouteName"].ToString()
                        };

                        lstTransportRoute.Add(oRouteDetails);
                    }
                }
            }

            return lstTransportRoute;
        }

